import pandas as pd
import os

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for f in files:
    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.xls'):
            # try reading with 'xlrd' or 'openpyxl' if compatible, but pandas default might work for .xls if xlrd is installed
            # Inspecting first 10 rows to see headers
            df = pd.read_excel(f, nrows=15) 
            print(df.head(15))
        else:
            df = pd.read_excel(f, nrows=15)
            print(df.head(15))
    except Exception as e:
        print(f"Error reading {f}: {e}")

